package com.gnostica.modules.settings.controller;
import com.gnostica.core.dto.response.ApiResponse; import com.gnostica.modules.settings.dto.request.*; import com.gnostica.modules.settings.dto.response.*; import com.gnostica.modules.settings.service.TermService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin/terms") @RequiredArgsConstructor @PreAuthorize("hasAnyAuthority('ADMIN','ROLE_ADMIN')") public class AdminTermsController { private final TermService service; @GetMapping public ApiResponse<List<TermModuleResponse>> tree(){return ApiResponse.success(service.adminTree());} @PostMapping("/modules") public ApiResponse<TermModuleResponse> createModule(@Valid @RequestBody TermModuleRequest r){return ApiResponse.success(service.createModule(r));} @PutMapping("/modules/{id}") public ApiResponse<TermModuleResponse> updateModule(@PathVariable Integer id,@Valid @RequestBody TermModuleRequest r){return ApiResponse.success(service.updateModule(id,r));} @DeleteMapping("/modules/{id}") public ApiResponse<Void> deleteModule(@PathVariable Integer id){service.deleteModule(id);return ApiResponse.success(null);} @PostMapping public ApiResponse<TermResponse> create(@Valid @RequestBody TermRequest r){return ApiResponse.success(service.createTerm(r));} @PutMapping("/{id}") public ApiResponse<TermResponse> update(@PathVariable Integer id,@Valid @RequestBody TermRequest r){return ApiResponse.success(service.updateTerm(id,r));} @DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Integer id){service.deleteTerm(id);return ApiResponse.success(null);} }
